import { UrlTree, DefaultUrlSerializer, UrlSerializer, Router } from '@angular/router';

export class cleanUrlSerializer extends DefaultUrlSerializer {

    override serialize(tree: UrlTree): string {

        const defaultUrl = super.serialize(tree);
        return defaultUrl
            .replace(/\(([^:]+:)?/, '')       // Removes opening '(' and optional outlet name prefix
            .replace(/\/\//g, '/')            // Cleans up accidental double slashes
            .replace(/\)/g, '');              // Removes closing ')'
    }
}